import {extractJpeg,measure} from './core.js';
self.onmessage=async({data:{id,file}})=>{let bitmap;try{const raw=/\.(arw|cr2|nef|dng|cr3|raf|rw2)$/i.test(file.name);const blob=raw?new Blob([extractJpeg(await file.arrayBuffer())],{type:'image/jpeg'}):file;bitmap=await createImageBitmap(blob,{imageOrientation:'from-image'});const width=bitmap.width,height=bitmap.height,scale=Math.min(1,320/Math.max(width,height)),w=Math.max(16,Math.round(width*scale)),h=Math.max(16,Math.round(height*scale)),canvas=new OffscreenCanvas(w,h),ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,w,h);const metrics=measure(ctx.getImageData(0,0,w,h).data,w,h);const preview=new OffscreenCanvas(Math.round(width*Math.min(1,1600/width)),Math.round(height*Math.min(1,1600/width)));preview.getContext('2d').drawImage(bitmap,0,0,preview.width,preview.height);self.postMessage({id,metrics,width,height,raw,preview:await preview.convertToBlob({type:'image/jpeg',quality:.85})});}catch(e){self.postMessage({id,error:e.message});}finally{bitmap?.close();}};
